#!/bin/bash
# Проверяет файлы тестового vault в симуляторе после UI-тестов (scripts/sim.sh load-vault → UI-тесты → этот скрипт).
set -uo pipefail
cd "$(dirname "$0")/.."
UDID="$(scripts/sim.sh udid)"
BUNDLE_ID="$(grep -E '^SP_BUNDLE_ID' Config/Shared.xcconfig | sed 's/.*= *//')"
VAULT="$(xcrun simctl get_app_container "$UDID" "$BUNDLE_ID" data)/Documents/TestVault"
TASKS="$VAULT/TaskNotes/Tasks"
# A task marked done goes to the done folder beside the tasks folder at once (rules.json → vault.doneFolder).
DONE="$VAULT/TaskNotes/Done"
TODAY="$(date +%Y-%m-%d)"
TOMORROW="$(date -v+1d +%Y-%m-%d)"
FAILED=0
check() { if eval "$2"; then echo "OK    $1"; else echo "FAIL  $1"; FAILED=1; fi; }

check "Habits: Done → complete_instances has today"  "grep -A20 '^complete_instances:' \"$TASKS/Медитация 🧘.md\" | grep -q \"$TODAY\""
check "long press Done → status done + completed_date, in Done" "grep -q '^status: done' \"$DONE/Оплатить интернет.md\" && grep -q \"^completed_date: $TODAY\" \"$DONE/Оплатить интернет.md\" && [ ! -f \"$TASKS/Оплатить интернет.md\" ]"
check "long press Done on a habit → complete_instances" "grep -A20 '^complete_instances:' \"$TASKS/Выпить воды 💧.md\" | grep -q \"$TODAY\""
check "task page High → priority: high"              "grep -q '^priority: high' \"$TASKS/Распечатать вопросы.md\""
check "habit page hex field → habit_color written"  "grep -qF '\"habit_color\":\"#34C759\"' \"$TASKS/Утро — завтрак 🥣.md\""
check "rename → new file, old gone"                  "[ -f \"$TASKS/Записать идеи 2.md\" ] && [ ! -f \"$TASKS/Записать идеи.md\" ]"
check "archive → status: archived"                   "grep -q '^status: archived' \"$TASKS/Купить батарейки 🔋.md\""
check "delete → moved to .trash"                     "[ -f \"$VAULT/.trash/Посмотреть сериал 🍿.md\" ] && [ ! -f \"$TASKS/Посмотреть сериал 🍿.md\" ]"
check "delete from Habits → repeatable task in .trash" "[ -f \"$VAULT/.trash/Витамины 💊.md\" ] && [ ! -f \"$TASKS/Витамины 💊.md\" ] && grep -qF '\"repeatable\":true' \"$VAULT/.trash/Витамины 💊.md\""
check "delete a parent → its subtasks in .trash too"  "[ -f \"$VAULT/.trash/Повесить зеркало.md\" ] && [ -f \"$VAULT/.trash/Купить дюбели.md\" ] && [ -f \"$VAULT/.trash/Найти уровень.md\" ] && [ ! -f \"$TASKS/Купить дюбели.md\" ]"
check "delete, Undo, delete, Restore from trash → back in the tasks" "[ -f \"$TASKS/Забрать посылку на почте.md\" ] && [ ! -f \"$VAULT/.trash/Забрать посылку на почте.md\" ]"
check "archive, Restore from archive (page menu) → status: this_week" "grep -q '^status: this_week' \"$TASKS/Собрать шкаф.md\""
check "picker → previous_task link written"          "grep -qF 'uid: \"[[Найти отвёртку]]\"' \"$TASKS/Помыть окна.md\""
check "event picker → previous_event written"        "grep -q '^previous_event: \".*|Call with dad|' \"$TASKS/Сходить к стоматологу.md\""
check "plus in Habits → new habit, in Today, black"  "grep -q '^status: habit' \"$TASKS/Читать 20 минут.md\" && grep -qF '\"show_in_today\":true' \"$TASKS/Читать 20 минут.md\" && grep -q '^recurrence: ' \"$TASKS/Читать 20 минут.md\" && grep -qF '\"habit_color\":\"#000000\"' \"$TASKS/Читать 20 минут.md\""
check "Return in a new task's name → saved once, edits after it written" "grep -q '^status: this_week' \"$TASKS/Купить хлеб.md\" && grep -q '^priority: high' \"$TASKS/Купить хлеб.md\" && [ ! -f \"$TASKS/Купить хлеб 2.md\" ] && [ -f \"$TASKS/Полить цветы.md\" ] && [ ! -f \"$TASKS/Полить цветы 2.md\" ] && [ ! -f \"$TASKS/Unnamed.md\" ]"
check "new item switched to Habit, Return → a habit, not in Today" "grep -q '^status: habit' \"$TASKS/Stretch.md\" && grep -q '^recurrence: ' \"$TASKS/Stretch.md\" && grep -qF '\"show_in_today\":false' \"$TASKS/Stretch.md\""
check "date chip → due with a time, no time zone" "grep -q '^due: [0-9-]*T[0-9:]*$' \"$TASKS/Оплатить аренду.md\" && ! grep -q 'time_zone' \"$TASKS/Оплатить аренду.md\""
check "blue date tapped in a new task's name → due tomorrow, words out of the name" "grep -q \"^due: $TOMORROW$\" \"$TASKS/Dentist.md\" && [ ! -f \"$TASKS/Dentist tomorrow.md\" ]"
check "subtask dragged → its place in subtask_order"  "grep -qF '\"subtask_order\":' \"$TASKS/Шаг один.md\""
check "swipe right in Habits → complete_instances"   "grep -A20 '^complete_instances:' \"$TASKS/Полить цветы 🌱.md\" | grep -q \"$TODAY\""
check "swipe left in a list → moved to .trash"        "[ -f \"$VAULT/.trash/Ждать ответа от арендодателя.md\" ] && [ ! -f \"$TASKS/Ждать ответа от арендодателя.md\" ]"
check "swipe right in a list → done, in Done"         "grep -q '^status: done' \"$DONE/Разобрать почту.md\" && [ ! -f \"$TASKS/Разобрать почту.md\" ]"
check "Return (menu) from Done → this_week, no completed_date" "grep -q '^status: this_week' \"$TASKS/Старая сделанная задача.md\" && ! grep -q '^completed_date:' \"$TASKS/Старая сделанная задача.md\" && [ ! -f \"$DONE/Старая сделанная задача.md\" ]"
check "Return (swipe) from Done → this_week, no completed_date" "grep -q '^status: this_week' \"$TASKS/Купить молоко.md\" && ! grep -q '^completed_date:' \"$TASKS/Купить молоко.md\" && [ ! -f \"$DONE/Купить молоко.md\" ]"
check "swipe left in Archive → status: this_week"     "grep -q '^status: this_week' \"$TASKS/Архивная задача.md\""
check "swipe left in Trash → back in the tasks"       "[ -f \"$TASKS/Связь на несуществующую.md\" ] && [ ! -f \"$VAULT/.trash/Связь на несуществующую.md\" ]"
check "habit block dragged to the pool and back → its note keeps its time" "grep -q '^due: .*T14:00$' \"$TASKS/Прогулка 🚶.md\" && ! grep -q 'reminder_times' \"$TASKS/Прогулка 🚶.md\" && ! grep -q \"^date_modified: $TODAY\" \"$TASKS/Прогулка 🚶.md\""
check "Start then Not started (pool menu) → this_week again" "grep -q '^status: this_week' \"$TASKS/Найти отвёртку.md\""
check "unknown keys and body untouched"              "grep -q '^  nested: значение' \"$TASKS/Длинная заметка с незнакомыми ключами.md\""
exit $FAILED
